 public function recordDelivery(Request$r,string$id,MealProgrammeService$s):JsonResponse{$this->enabled();$d=$r->validate(['lines'=>['required','array','min:1'],'lines.*.menu_item_id'=>['required','uuid'],'lines.*.delivered_quantity'=>['required','integer','min:0'],'lines.*.accepted_quantity'=>['required','integer','min:0'],'lines.*.consumed_quantity'=>['required','integer','min:0'],'lines.*.wasted_quantity'=>['required','integer','min:0'],'lines.*.variance_reason'=>['nullable','string','max:2000'],'delivery_evidence'=>['required','array']]);return DB::transaction(function()use($r,$id,$d,$s){$o=DB::table('hr_meal_vendor_orders')->where('id',$id)->lockForUpdate()->first();abort_unless($o,404);$this->company($r,$o->company_id);abort_unless($o->status==='approved',409);foreach($d['lines']as$line){$stored=DB::table('hr_meal_vendor_order_lines')->where('vendor_order_id',$id)->where('menu_item_id',$line['menu_item_id'])->lockForUpdate()->first();abort_unless($stored,422);abort_if($line['accepted_quantity']>$line['delivered_quantity']||$line['consumed_quantity']+$line['wasted_quantity']>$line['accepted_quantity'],422,'Delivery quantities do not reconcile.');if($line['delivered_quantity']!==$stored->ordered_quantity||$line['accepted_quantity']!==$line['delivered_quantity'])abort_unless(!empty($line['variance_reason']),422,'Variance reason is required.');DB::table('hr_meal_vendor_order_lines')->where('id',$stored->id)->update(['delivered_quantity'=>$line['delivered_quantity'],'accepted_quantity'=>$line['accepted_quantity'],'consumed_quantity'=>$line['consumed_quantity'],'wasted_quantity'=>$line['wasted_quantity'],'variance_reason'=>$line['variance_reason']??null,'updated_at'=>now()]);}DB::table('hr_meal_vendor_orders')->where('id',$id)->update(['status'=>'delivered','delivered_at'=>now(),'delivery_snapshot'=>json_encode($d['delivery_evidence'],JSON_THROW_ON_ERROR),'updated_at'=>now()]);$s->event('vendor_order',$id,'delivery_recorded','approved','delivered',['line_count'=>cou