 public function reconcile(Request$r,string$id,MealProgrammeService$s):JsonResponse{$this->enabled();return DB::transaction(function()use($r,$id,$s){$o=DB::table('hr_meal_vendor_orders')->where('id',$id)->lockForUpdate()->first();abort_unless($o,404);$this->company($r,$o->company_id);abort_unless($o->status==='delivered',409);$lines=DB::table('hr_meal_vendor_order_lines')->where('vendor_order_id',$id)->get();abort_if($lines->contains(fn($line)=>$line->delivered_quantity===null||$line->accepted_quantity!==$line->ordered_quantity||($line->consumed_quantity+$line->wasted_quantity)!==$line->accepted_quantity),409,'Delivery variance must be resolved through a governed credit/substitution/allocation adjustment before finance reconciliation.');$program=DB::table('hr_meal_program_versions')->find($o->program_version_id);$vendor=DB::table('hr_meal_vendors')->find($o->vendor_id);$employeeOrders=DB::table('hr_meal_employee_orders')->where('program_version_id',$o->program_version_id)->whereDate('service_date',$o->service_date)->get();$payload=['vendor_order_id'=>$id,'supplier_reference'=>$vendor->canonical_supplier_reference,'vendor_id'=>$vendor->id,'service_date'=>$o->service_date,'supplier_payable_amount'=>$o->total_amount,'employer_expense_amount'=>$o->employer_amount,'employee_recovery_amount'=>$o->employee_amount,'employee_recovery_mode'=>$program->employee_recovery_mode,'currency'=>$o->currency,'order_checksum'=>$o->order_checksum,'employee_allocations'=>$employeeOrders->map(fn($x)=>['employee_order_id'=>$x->id,'staff_id'=>$x->staff_id,'employee_share_amount'=>$x->employee_share_amount])->values()->all(),'direct_and_payroll_mutually_exclusive'=>true];DB::table('hr_accounting_outbox')->insert(['id'=>(string)Str::uuid(),'company_id'=>$o->company_id,'event_type'=>'meal_vendor_order_reconciled','aggregate_type'=>'meal_vendor_order','aggregate_id'=>$id,'payload'=>json_encode($payload,JSON_THROW_ON_ERROR),'payload_checksum'=>hash('sha256',json_encode($payload,JSON_UNESCAPED_SLA